/* From Uiverse.io by jack0237  - Tags:  */
.__UIV_SCOPE__ .loader {
  display: flex;
}

.__UIV_SCOPE__ .loader .dot {
  height: 20px;
  width: 20px;
  border-radius: 50%;
  border: 2px solid #e8e8e8;
  background: #16b0c1;
  animation: jump 0.8s ease-in-out infinite alternate;
}

@keyframes jump {
  100% {
    background: #661e92;
    transform: translateY(-3rem) scale(1.9);
  }
}

.__UIV_SCOPE__ .loader .dot:nth-child(1) {
  animation-delay: 0.1s;
}

.__UIV_SCOPE__ .loader .dot:nth-child(2) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .loader .dot:nth-child(3) {
  animation-delay: 0.3s;
}

.__UIV_SCOPE__ .loader .dot:nth-child(4) {
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .loader .dot:nth-child(5) {
  animation-delay: 0.5s;
}
